function drawMinimap() {
  mctx.clearRect(0, 0, 150, 150);
  mctx.fillStyle = 'rgba(0,0,0,0.3)';
  mctx.beginPath();
  mctx.arc(75, 75, 73, 0, Math.PI * 2);
  mctx.fill();

  // Arena border
  mctx.strokeStyle = 'rgba(0,255,255,0.3)';
  mctx.lineWidth = 1;
  mctx.beginPath();
  mctx.arc(75, 75, 70, 0, Math.PI * 2);
  mctx.stroke();

  // Player
  const px = 75 + (STATE.playerPos.x / ARENA_RADIUS) * 70;
  const py = 75 + (STATE.playerPos.z / ARENA_RADIUS) * 70;
  mctx.fillStyle = '#00ffff';
  mctx.beginPath();
  mctx.arc(px, py, 4, 0, Math.PI * 2);
  mctx.fill();

  // Enemies
  STATE.enemies.forEach(e => {
    const ex = 75 + (e.position.x / ARENA_RADIUS) * 70;
    const ey = 75 + (e.position.z / ARENA_RADIUS) * 70;
    mctx.fillStyle = e.userData.type === 'tank' ? '#aa00ff' : '#ff2244';
    mctx.beginPath();
    mctx.arc(ex, ey, e.userData.type === 'tank' ? 3 : 2, 0, Math.PI * 2);
    mctx.fill();
  });

  // Pickups
  STATE.pickups.forEach(p => {
    const ppx = 75 + (p.position.x / ARENA_RADIUS) * 70;
    const ppy = 75 + (p.position.z / ARENA_RADIUS) * 70;
    mctx.fillStyle = '#ffaa00';
    mctx.beginPath();
    mctx.arc(ppx, ppy, 2, 0, Math.PI * 2);
    mctx.fill();
  });
}

// ============ INPUT ============
document.addEventListener('keydown', e => {
  STATE.keys[e.code] = true;
  if (e.code === 'KeyR' && STATE.isRunning) {
    // Instant heal
    STATE.health = Math.min(STATE.maxHealth, STATE.health + 5);
    updateHealthBar();
  }
});
document.addEventListener('keyup', e => STATE.keys[e.code] = false);

document.addEventListener('mousemove', e => {
  if (!STATE.isRunning) return;
  STATE.cameraAngle -= e.movementX * 0.003;
  STATE.cameraPitch += e.movementY * 0.002;
  STATE.cameraPitch = Math.max(-0.5, Math.min(1.2, STATE.cameraPitch));
});

document.addEventListener('mousedown', e => {
  if (!STATE.isRunning) return;
  if (document.pointerLockElement !== renderer.domElement) {
    renderer.domElement.requestPointerLock();
    return;
  }
  shoot();
});

document.addEventListener('pointerlockchange', () => {
  if (!STATE.isRunning && document.pointerLockElement === renderer.domElement) {
    document.exitPointerLock();
  }
});

document.getElementById('start-btn').addEventListener('click', startGame);
document.getElementById('restart-btn').addEventListener('click', startGame);

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ============ GAME LOOP ============
let lastTime = 0;
function gameLoop(time) {
  requestAnimationFrame(gameLoop);
  const dt = Math.min((time - lastTime) / 16.67, 3);
  lastTime = time;

  if (!STATE.isRunning) {
    renderer.render(scene, camera);
    return;
  }

  updatePlayer(dt);
  updateCamera();
  updateEnemies();
  updateBullets();
  updateParticles();
  updatePickups();
  updateWave();
  drawMinimap();

  // Animate corner lights
  cornerLights.forEach((light, i) => {
    light.intensity = 0.3 + Math.sin(time * 0.002 + i) * 0.2;
  });

  renderer.render(scene, camera);
}

requestAnimationFrame(gameLoop);
</script>
</body>
</html>
